package dev.veltraph.client.navigation;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import dev.veltraph.client.world.Vec3;import java.util.*;
final class WaterTerminalHoldTest {
 final Vec3 goal=new Vec3(.5,70,.5);final WaterTravelController.Geometry clear=new WaterTravelController.Geometry(){public boolean connection(Vec3 a,Vec3 b){return true;}public boolean ground(Vec3 p){return true;}public boolean water(Vec3 p){return true;}};
 WaterTravelController.Input input(Vec3 p,Vec3 v,float yaw,boolean available,boolean lava,int air,long now){return new WaterTravelController.Input(p,v,yaw,true,true,false,air,300,20,available,lava,true,now);}
 WaterTravelController arrived(){var c=new WaterTravelController();c.start(List.of(goal),20,0,.18);assertEquals(WaterTravelController.State.ARRIVED,c.tick(input(goal,new Vec3(0,0,0),-90,true,false,300,1),clear,6000,1).state());return c;}
 boolean moving(WaterTravelController.Output o){return o.forward()||o.back()||o.left()||o.right();}
 @Test void retainedArrivedPlanRecentersMeasuredWaterflowWithoutCameraHeading(){var c=arrived();var checkpoint=c.maintenanceState();var o=c.tickTerminalHold(input(new Vec3(.3000000119,70,.4232819955),new Vec3(0,-.005,0),-22.52124f,true,false,300,2),clear);assertTrue(moving(o));assertEquals(-22.52124f,o.yaw());assertEquals(WaterTravelController.State.TRAVELLING,o.state());for(String field:List.of("route","index","terminalRadius","heading","progressAt","refillAt"))assertEquals(checkpoint.fields().get(field),c.maintenanceState().fields().get(field),field);assertEquals(WaterTravelController.State.ARRIVED,c.state(),"Retained receipt remains same completed plan");}
 @Test void actualYawProjectsMovementAndInsideRadiusRetainsCentering(){for(float yaw:new float[]{0,90,180,-90}){var c=arrived();var o=c.tickTerminalHold(input(new Vec3(.4,70,.45),new Vec3(0,0,0),yaw,true,false,300,2),clear);assertTrue(moving(o));assertEquals(yaw,o.yaw());}var c=arrived();assertFalse(moving(c.tickTerminalHold(input(goal,new Vec3(0,0,0),0,true,false,300,2),clear)));}
 @Test void defaultArrivedStillReleasesAndUnarrivedOrLegacyPlanCannotHold(){var c=arrived();assertFalse(moving(c.tick(input(new Vec3(.3,70,.42),new Vec3(0,0,0),0,true,false,300,2),clear,6000,1)));var legacy=new WaterTravelController();legacy.start(List.of(goal),20,0);legacy.tick(input(goal,new Vec3(0,0,0),0,true,false,300,1),clear,6000,1);assertFalse(legacy.terminalHoldReady());assertEquals(WaterTravelController.State.BLOCKED,legacy.tickTerminalHold(input(goal,new Vec3(0,0,0),0,true,false,300,2),clear).state());var active=new WaterTravelController();active.start(List.of(goal),20,0,.18);assertEquals(WaterTravelController.State.BLOCKED,active.tickTerminalHold(input(goal,new Vec3(0,0,0),0,true,false,300,1),clear).state());}
 @Test void collisionLavaAvailabilityAirAndHealthRemainFailClosed(){for(int which=0;which<5;which++){var c=arrived();var geometry=which==0?new WaterTravelController.Geometry(){public boolean connection(Vec3 a,Vec3 b){return false;}public boolean ground(Vec3 p){return false;}public boolean water(Vec3 p){return false;}}:clear;var in=input(goal,new Vec3(0,0,0),0,which!=1,which==2,which==3?0:300,2);if(which==4)in=new WaterTravelController.Input(goal,new Vec3(0,0,0),0,true,true,false,300,300,19,true,false,true,2);var o=c.tickTerminalHold(in,geometry);assertEquals(WaterTravelController.State.BLOCKED,o.state());assertFalse(moving(o));}}
}
